def choose_move(observation):
    player_pos = observation.get('player', {}).get('pos', (0, 0))
    resources = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    goals = observation.get('goals', [])
    territory = observation.get('territory', [])
    grid = observation.get('grid', [])

    def get_closest(targets, pos):
        min_dist = float('inf')
        closest_target = None
        for t in targets:
            dist = abs(pos[0] - t[0]) + abs(pos[1] - t[1])
            if dist < min_dist:
                min_dist = dist
                closest_target = t
        return closest_target

    # Prioritize pursuit of opponents within 3 units
    target_pos = None
    for opp in opponents:
        opp_pos = opp.get('pos')
        if opp_pos:
            dist = abs(player_pos[0] - opp_pos[0]) + abs(player_pos[1] - opp_pos[1])
            if dist <= 3:
                target_pos = opp_pos
                break
    if target_pos is None:
        if resources:
            target_pos = get_closest(resources, player_pos)
        elif goals:
            target_pos = get_closest(goals, player_pos)
        elif territory:
            target_pos = get_closest(territory, player_pos)
        else:
            grid_rows = len(grid)
            grid_cols = len(grid[0]) if grid else 0
            target_pos = (grid_rows // 2, grid_cols // 2)

    delta_x = target_pos[0] - player_pos[0]
    delta_y = target_pos[1] - player_pos[1]
    dx = (1 if delta_x > 0 else -1) if delta_x != 0 else 0
    dy = (1 if delta_y > 0 else -1) if delta_y != 0 else 0

    def is_valid(x, y):
        return len(grid) > x >= 0 and len(grid[0]) > y >= 0

    new_x = player_pos[0] + dx
    new_y = player_pos[1] + dy

    if is_valid(new_x, new_y):
        if grid[new_x][new_y] == 0:
            return [dx, dy]
        else:
            # Try alternative directions for better chance
            for alt_dx, alt_dy in [(-dy, dx), (dy, -dx), (0, 0)]:
                alt_x = player_pos[0] + alt_dx
                alt_y = player_pos[1] + alt_dy
                if is_valid(alt_x, alt_y):
                    if grid[alt_x][alt_y] == 0:
                        return [alt_dx, alt_dy]
    # Default to no movement
    return [0, 0]

